// Daily follow-ups for leads still at Stage "New": day 1, 3, 7 and 14
// after Submitted At, by email only, one per run, then stop. Moving
// Stage off "New" (any value) stops them at once. Nothing here sends a
// WhatsApp message; links to WhatsApp are click-to-chat only.
const SITE = 'https://aniket-portfolio-six-bice.vercel.app';
const ANIKET_WA = 'https://wa.me/919136582842';
const BOOKING_URL = '';
const DAYS = [1, 3, 7, 14];

// The one case study per area, with its honest label.
const READ = {
  websites: { title: 'Website Answer Widget', url: `${SITE}/projects/website-answer-widget`, label: 'a working demo on dummy data, not a client project', what: 'a chat bubble on a clinic website that answers from the clinic\'s own documents and takes a callback when it can\'t' },
  software: { title: 'Clinic Staff App', url: `${SITE}/projects/therapist-pwa`, label: 'a real system an eleven-therapist clinic runs its day on', what: 'client records, bookings, consent forms and AI-drafted session notes the therapist approves' },
  ai: { title: 'Appointment Desk', url: `${SITE}/projects/appointment-desk`, label: 'a working demo on dummy data, not a client project', what: 'an AI front desk that answers fees and hours, books free slots and hands anything clinical to a person' },
  form: { title: 'the projects page', url: `${SITE}/projects`, label: 'client work and working demos, each labelled', what: 'websites, software and AI built for service businesses' }
};
const OBSTACLE = {
  websites: 'The question I hear most about websites is "what will it really cost, and will it actually be finished?" The price is fixed in writing before anything starts, with the date it goes live. Half up front, half on delivery, and if it isn\'t live by that date you don\'t pay the second half. The domain and the site are set up in your name.',
  software: 'The question I hear most about software is "will we be locked in?" Everything runs on your own accounts and is set up in your name, and handover includes a walkthrough so your team can change the obvious things without calling me. The price and the live date are fixed in writing first.',
  ai: 'The question I hear most about AI is "will it make things up?" It answers from the information you give it, and wherever a wrong answer would cost you, a person checks it first. In the clinic system on my site the AI drafts the session note and the therapist approves it before it is saved.',
  form: 'The question I hear most is "what will it really cost?" Every project has a fixed price and a live date in writing before anything starts. Half up front, half on delivery, and if it isn\'t live by that date you don\'t pay the second half.'
};

const book = BOOKING_URL
  ? `Book a free 15-minute call: ${BOOKING_URL}`
  : `Reply with two times that suit you for a free 15-minute call, or message me on WhatsApp: ${ANIKET_WA}`;

const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if ((r.Stage || '').trim() !== 'New') continue;
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.Email || '')) continue;
  const at = Date.parse(r['Submitted At']);
  if (!Number.isFinite(at)) continue;
  const days = Math.floor((now - at) / 86400000);
  const sent = Number(r['Follow-ups sent']) || 0;
  if (sent >= DAYS.length || days < DAYS[sent]) continue;

  const first = (r.Name || '').split(' ')[0] || 'there';
  const src = (r.Source || '').toLowerCase();
  const kind = src.startsWith('start-website') ? 'websites'
    : src.startsWith('start-software') ? 'software'
    : src.startsWith('ai-check') ? 'ai'
    : 'form';
  const plan = { websites: 'website plan', software: 'software plan', ai: 'AI check', form: 'message' }[kind];
  const pkg = (r.Package || '').split(' (')[0];
  const read = READ[kind];
  let subject;
  let body;
  if (sent === 0) {
    subject = `One question about your ${plan}`;
    body = `Hi ${first},\n\nI've looked at your ${plan}${pkg ? ' (the ' + pkg + ')' : ''}. One question before we talk: what would make this worth doing for you? More enquiries, fewer hours on admin, or something else?\n\nA line in reply is plenty. ${book}\n\nAniket`;
  } else if (sent === 1) {
    subject = `Something like what you described: ${read.title}`;
    body = `Hi ${first},\n\nOne thing on my site that is close to what you described: ${read.title}, ${read.what}. It is ${read.label}.\n\n${read.url}\n\nIf it is near what you need, ${book.charAt(0).toLowerCase() + book.slice(1)}\n\nAniket`;
  } else if (sent === 2) {
    subject = 'The question I hear most';
    body = `Hi ${first},\n\n${OBSTACLE[kind]}\n\nIf that was what held you back, ${book.charAt(0).toLowerCase() + book.slice(1)}\n\nAniket`;
  } else {
    const later = /1 to 3 months/i.test(r.Timing || '') ? 'in a month or so' : 'in a few weeks';
    subject = `Should I close your ${plan}?`;
    body = `Hi ${first},\n\nI haven't heard back, which is completely fine. Should I close your ${plan}? If the timing is just wrong, reply "later" and I'll check in ${later}. Otherwise this is my last email about it.\n\nAniket\n${SITE}`;
  }
  out.push({ json: { row_number: r.row_number, Email: r.Email, _subject: subject, _body: body, 'Follow-ups sent': sent + 1, 'Last follow-up': new Date(now).toISOString() } });
}
return out;
